/** What the console can observe about a running child process. */
export interface ProcessHandle {
  /** Raw output chunks written so far (may contain ANSI escapes and \r). */
  output(): string[];
  /** Exit code once the process has exited, otherwise null. */
  exitCode(): number | null;
}

export interface ScriptStep {
  /** Milliseconds after the process was started. */
  at: number;
  write?: string;
  exit?: number;
}

/** Deterministic stand-in for a child process, driven by the console clock. */
export class ScriptedProcess implements ProcessHandle {
  private readonly startedAt: number;

  constructor(private readonly steps: ScriptStep[], private readonly now: () => number) {
    this.startedAt = now();
  }

  output(): string[] {
    const t = this.now() - this.startedAt;
    return this.steps.filter((s) => s.at <= t && s.write !== undefined).map((s) => s.write as string);
  }

  exitCode(): number | null {
    const t = this.now() - this.startedAt;
    const exit = this.steps.find((s) => s.exit !== undefined && s.at <= t);
    return exit ? (exit.exit as number) : null;
  }
}
import { collapseCarriageReturns, stripAnsi } from "../util/ansi";
import { ProcessHandle } from "./process";

/** Turns raw process output into display lines. */
export class OutputTail {
  constructor(private readonly proc: ProcessHandle) {}

  read(): string[] {
    const text = this.proc.output().join("");
    const lines = text.split("\n");
    if (lines[lines.length - 1] === "") lines.pop();
    return lines.map((l) => collapseCarriageReturns(stripAnsi(l)));
  }
}
import { JobEvent } from "../domain/events";
import { ProcessHandle } from "../runtime/process";
import { EventBus } from "../transport/eventBus";
import { Clock } from "../util/clock";

/** Announces process exit as soon as it is observed. */
export class ExitWatcher {
  private closed = false;

  constructor(
    private readonly jobId: string,
    private readonly proc: ProcessHandle,
    private readonly bus: EventBus<JobEvent>,
    private readonly clock: Clock,
    private readonly onExit: (code: number) => void,
  ) {}

  tick(): void {
    if (this.closed) return;
    const code = this.proc.exitCode();
    if (code === null) return;
    this.closed = true;
    this.bus.publish("control", { kind: "closed", jobId: this.jobId, exitCode: code, at: this.clock.now() });
    this.onExit(code);
  }

  isClosed(): boolean {
    return this.closed;
  }
}
import { ConsoleConfig } from "../config";
import { JobEvent } from "../domain/events";
import { OutputTail } from "../runtime/tail";
import { EventBus } from "../transport/eventBus";
import { Clock } from "../util/clock";
import { fingerprint } from "../util/fingerprint";

/**
 * Polls one job's output every tick and publishes log snapshots.
 * Snapshots are coalesced: at most one per `emitMinIntervalMs`; a change that
 * arrives inside the window goes out with the first tick after it.
 */
export class LogPump {
  private lastFp: string | null = null;
  private unsent: string[] | null = null;
  private lastEmit = Number.NEGATIVE_INFINITY;
  private seq = 0;
  private stopped = false;

  constructor(
    private readonly jobId: string,
    private readonly tail: OutputTail,
    private readonly bus: EventBus<JobEvent>,
    private readonly clock: Clock,
    private readonly config: ConsoleConfig,
  ) {}

  tick(): void {
    if (this.stopped) return;
    const lines = this.tail.read();
    const fp = fingerprint(lines);
    if (fp !== this.lastFp) {
      this.lastFp = fp;
      this.unsent = lines;
    }
    const now = this.clock.now();
    if (this.unsent !== null && now - this.lastEmit >= this.config.emitMinIntervalMs) {
      this.bus.publish("data", { kind: "timeline", jobId: this.jobId, seq: ++this.seq, lines: this.unsent });
      this.unsent = null;
      this.lastEmit = now;
    }
  }

  stop(): void {
    this.stopped = true;
  }

  sent(): number {
    return this.seq;
  }
}
import { ConsoleConfig } from "../config";
import { JobEvent } from "../domain/events";
import { ProcessHandle } from "../runtime/process";
import { OutputTail } from "../runtime/tail";
import { EventBus } from "../transport/eventBus";
import { Clock } from "../util/clock";
import { ExitWatcher } from "./exitWatcher";
import { LogPump } from "./logPump";

interface Running {
  pump: LogPump;
  watcher: ExitWatcher;
}

/** Owns the per-job pump and exit watcher; driven by the host loop. */
export class Supervisor {
  private readonly running = new Map<string, Running>();

  constructor(
    private readonly bus: EventBus<JobEvent>,
    private readonly clock: Clock,
    private readonly config: ConsoleConfig,
  ) {}

  attach(jobId: string, name: string, proc: ProcessHandle): void {
    if (this.running.has(jobId)) throw new Error(`job ${jobId} already attached`);
    const pump = new LogPump(jobId, new OutputTail(proc), this.bus, this.clock, this.config);
    const watcher = new ExitWatcher(jobId, proc, this.bus, this.clock, () => this.detach(jobId));
    this.running.set(jobId, { pump, watcher });
    this.bus.publish("control", { kind: "started", jobId, name, at: this.clock.now() });
  }

  tick(): void {
    for (const { pump, watcher } of [...this.running.values()]) {
      pump.tick();
      watcher.tick();
    }
  }

  activeJobs(): string[] {
    return [...this.running.keys()];
  }

  private detach(jobId: string): void {
    const r = this.running.get(jobId);
    if (!r) return;
    r.pump.stop();
    this.running.delete(jobId);
  }
}
import { JobEvent } from "../domain/events";
import { JobView, statusForExit } from "../domain/job";
import { JobViewStore } from "../store/jobViewStore";

/** Folds job events into the read model the console API serves. */
export class JobProjection {
  constructor(private readonly store: JobViewStore) {}

  apply(e: JobEvent): void {
    switch (e.kind) {
      case "started":
        this.store.put({
          id: e.jobId,
          name: e.name,
          status: "running",
          exitCode: null,
          log: [],
          seq: 0,
          startedAt: e.at,
          endedAt: null,
        });
        return;
      case "timeline": {
        const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
        if (e.seq <= view.seq) return; // stale snapshot
        this.store.put({ ...view, status: "running", log: e.lines, seq: e.seq });
        return;
      }
      case "closed": {
        const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
        this.store.put({ ...view, status: statusForExit(e.exitCode), exitCode: e.exitCode, endedAt: e.at });
        return;
      }
    }
  }

  private blank(id: string): JobView {
    return { id, name: id, status: "running", exitCode: null, log: [], seq: 0, startedAt: 0, endedAt: null };
  }
}
export interface StartedEvent {
  kind: "started";
  jobId: string;
  name: string;
  at: number;
}

/** Full log snapshot so far. `seq` increases per job. */
export interface TimelineEvent {
  kind: "timeline";
  jobId: string;
  seq: number;
  lines: string[];
}

export interface ClosedEvent {
  kind: "closed";
  jobId: string;
  exitCode: number;
  at: number;
}

export type JobEvent = StartedEvent | TimelineEvent | ClosedEvent;

export function isJobEvent(x: unknown): x is JobEvent {
  if (typeof x !== "object" || x === null) return false;
  const e = x as { kind?: unknown; jobId?: unknown };
  if (typeof e.jobId !== "string") return false;
  return e.kind === "started" || e.kind === "timeline" || e.kind === "closed";
}
export type JobStatus = "running" | "succeeded" | "failed";

export interface JobView {
  id: string;
  name: string;
  status: JobStatus;
  exitCode: number | null;
  log: string[];
  seq: number;
  startedAt: number;
  endedAt: number | null;
}

export function statusForExit(code: number): JobStatus {
  return code === 0 ? "succeeded" : "failed";
}

export function isFinished(v: JobView): boolean {
  return v.status !== "running";
}
